from datetime import datetime, timedelta

# Parameters
day = "Monday"
meeting_duration = timedelta(minutes=30)

work_start = datetime.strptime("09:00", "%H:%M")
work_end   = datetime.strptime("17:00", "%H:%M")

# Participants' schedules
# Deborah: free whole day within work hours
deborah_busy = []  # no busy intervals

# Albert: busy intervals and cannot meet after 11:00
albert_busy_strings = [
    ("09:00", "10:00"),
    ("10:30", "12:00"),
    ("15:00", "16:30"),
    ("11:00", "17:00")  # cannot meet after 11:00
]
def parse_interval(s):
    start = datetime.strptime(s[0], "%H:%M")
    end   = datetime.strptime(s[1], "%H:%M")
    return (start, end)
albert_busy = [parse_interval(p) for p in albert_busy_strings]

def merge_intervals(intervals):
    """Merge overlapping intervals."""
    if not intervals:
        return []
    intervals = sorted(intervals, key=lambda x: x[0])
    merged = [intervals[0]]
    for cur_start, cur_end in intervals[1:]:
        last_start, last_end = merged[-1]
        if cur_start <= last_end:
            merged[-1] = (last_start, max(last_end, cur_end))
        else:
            merged.append((cur_start, cur_end))
    return merged

def invert_intervals(busy, overall_start, overall_end):
    """Return free intervals within overall range."""
    free = []
    current = overall_start
    for start, end in busy:
        if current < start:
            free.append((current, start))
        current = max(current, end)
    if current < overall_end:
        free.append((current, overall_end))
    return free

# Compute free intervals for each participant within work hours
deborah_free = [(work_start, work_end)]

albert_busy_merged = merge_intervals(albert_busy)
albert_free = invert_intervals(albert_busy_merged, work_start, work_end)

