import datetime

def time_to_min(t: str) -> int:
    h, m = map(int, t.split(":"))
    return h * 60 + m

def min_to_time(m: int) -> str:
    return f"{m // 60:02d}:{m % 60:02d}"

def complement_intervals(busy, work_start, work_end):
    """Return free intervals within work window given sorted busy intervals."""
    free = []
    cur = work_start
    for s, e in busy:
        if s > cur:
            free.append((cur, s))
        cur = max(cur, e)
    if cur < work_end:
        free.append((cur, work_end))
    return free

def intersect_intervals(a, b):
    """Intersect two lists of intervals."""
    i, j = 0, 0
    result = []
    while i < len(a) and j < len(b):
        s1, e1 = a[i]
        s2, e2 = b[j]
        start = max(s1, s2)
        end = min(e1, e2)
        if start < end:
            result.append((start, end))
        if e1 < e2:
            i += 1
        else:
            j += 1
    return result

