from datetime import datetime, timedelta

# Helper functions
def time_to_min(t: str) -> int:
    h, m = map(int, t.split(":"))
    return h * 60 + m

def min_to_time(m: int) -> str:
    h = m // 60
    mins = m % 60
    return f"{h:02d}:{mins:02d}"

def subtract_intervals(available, blocked):
    """Subtract blocked intervals from available intervals."""
    result = []
    for a_start, a_end in available:
        cur_start = a_start
        for b_start, b_end in blocked:
            if b_end <= cur_start or b_start >= a_end:
                continue  # no overlap
            if b_start <= cur_start < b_end:
                cur_start = b_end  # shift start forward
            elif cur_start < b_start < a_end:
                result.append((cur_start, b_start))
                cur_start = b_end
        if cur_start < a_end:
            result.append((cur_start, a_end))
    return result

def intersect_intervals(a, b):
    """Return intersection of two interval lists."""
    i, j = 0, 0
    result = []
    while i < len(a) and j < len(b):
        start = max(a[i][0], b[j][0])
        end = min(a[i][1], b[j][1])
        if start < end:
            result.append((start, end))
        if a[i][1] < b[j][1]:
            i += 1
        else:
            j += 1
    return result

# Data definition
work_start = time_to_min("09:00")
work_end = time_to_min("17:00")
meeting_len = 30  # minutes

participants = {
    "Margaret": {
        "Monday": [("10:30", "11:00"), ("11:30", "12:00"),
                   ("13:00", "13:30"), ("15:00", "17:00")],
        "Tuesday": [("12:00", "12:30")]
    },
    "Alexis": {
        "Monday": [("09:30", "11:30"), ("12:30", "13:00"),
                   ("14:00", "17:00")],
        "Tuesday": [("09:00", "09:30"), ("10:00", "10:30"),
                    ("14:00", "16:30")]
    }
}

# Convert blocked strings to minute intervals
for person in participants:
    for day in participants[person]:
        participants[person][day] = [
            (time_to_min(s), time_to_min(e))
            for s, e in participants[person][day]
        ]

# Margaret's personal constraints
def apply_margaret_constraints(day, intervals):
    if day == "Monday":
        return []  # she does not want to meet Monday
    if day == "Tuesday":
        earliest = time_to_min("14:30")
        filtered = []
        for s, e in intervals:
            if e <= earliest:
                continue
            filtered.append((max(s, earliest), e))
        return filtered
    return intervals

# Search for a feasible slot
solution = None
for day in ["Monday", "Tuesday"]:
    # start from full work interval
    base = [(work_start, work_end)]
    # compute free intervals for each participant
    free_lists = []
    for person in participants:
        blocked = participants[person].get(day, [])
        free = subtract_intervals(base, blocked)
        if person == "Margaret":
            free = apply_margaret_constraints(day, free)
        free_lists.append(free)
    # intersect all free intervals
    common = free_lists[0]
    for other in free_lists[1:]:
        common = intersect_intervals(common, other)
        if not common:
            break
    # find first interval long enough
    for s, e in common:
        if e - s >= meeting_len:
            solution = (day, min_to_time(s), min_to_time(s + meeting_len))
            break
    if solution:
        break

# Output in required format
print([solution[0], solution[1], solution[2]])

import sys

DAY_ORDER = ["Tuesday", "Wednesday", "Monday"]  # prefer non‑Monday days
WORK_START = 9 * 60
WORK_END = 17 * 60
MEETING_DURATION = 30  # minutes

def to_min(t: str) -> int:
    h, m = map(int, t.split(":"))
    return h * 60 + m

def to_str(m: int) -> str:
    return f"{m // 60:02d}:{m % 60:02d}"

def free_intervals(busy):
    """busy: list of (start_min, end_min) within work hours, sorted, non‑overlapping"""
    free = []
    prev_end = WORK_START
    for s, e in busy:
        if s > prev_end:
            free.append((prev_end, s))
        prev_end = max(prev_end, e)
    if prev_end < WORK_END:
        free.append((prev_end, WORK_END))
    return free

def intersect_intervals(a, b):
    """yield overlapping intervals of a and b (both sorted)"""
    i = j = 0
    while i < len(a) and j < len(b):
        s = max(a[i][0], b[j][0])
        e = min(a[i][1], b[j][1])
        if e - s >= MEETING_DURATION:
            yield (s, e)
        if a[i][1] < b[j][1]:
            i += 1
        else:
            j += 1

# schedules (busy intervals) for each participant per day
robert = {
    "Monday": [("11:00","11:30"), ("14:00","14:30"), ("15:30","16:00")],
    "Tuesday": [("10:30","11:00"), ("15:00","15:30")],
    "Wednesday": [("10:00","11:00"), ("11:30","12:00"), ("12:30","13:00"),
                  ("13:30","14:00"), ("15:00","15:30"), ("16:00","16:30")]
}
ralph = {
    "Monday": [("10:00","13:30"), ("14:00","14:30"), ("15:00","17:00")],
    "Tuesday": [("09:00","09:30"), ("10:00","10:30"), ("11:00","11:30"),
                ("12:00","13:00"), ("14:00","15:30"), ("16:00","17:00")],
    "Wednesday": [("10:30","11:00"), ("11:30","12:00"),
                  ("13:00","14:30"), ("16:30","17:00")]
}

# convert string times to minutes
def parse_schedule(sched):
    out = {}
    for day, intervals in sched.items():
        mins = [(to_min(s), to_min(e)) for s, e in intervals]
        mins.sort()
        out[day] = mins
    return out

robert_min = parse_schedule(robert)
ralph_min = parse_schedule(ralph)

def earliest_meeting():
    for day in DAY_ORDER:
        busy_r = robert_min.get(day, [])
        busy_l = ralph_min.get(day, [])
        free_r = free_intervals(busy_r)
        free_l = free_intervals(busy_l)
        for s, e in intersect_intervals(free_r, free_l):
            # earliest start within this overlapping interval
            start = s
            end = start + MEETING_DURATION
            if end <= e:
                return day, to_str(start), to_str(end)
    return None

result = earliest_meeting()
if result:
    print([result[0], result[1], result[2]])
else:
    sys.exit("No feasible meeting time found")

# Meeting scheduler for Betty and Scott
# Constraints:
# - Meeting duration: 30 minutes
# - Work hours: 09:00‑17:00
# - Days considered: Monday‑Thursday
# - Betty cannot meet on Monday or Tuesday; on Thursday only at/after 15:00
# - Prefer a slot that is NOT on Wednesday if possible

from datetime import timedelta

# Helper to convert "HH:MM" to minutes since midnight
def to_min(t):
