        busy[person][day] = [(to_min(s), to_min(e)) for s, e in busy[person][day]]

WORK_START = to_min('09:00')
WORK_END   = to_min('17:00')
DURATION   = 30  # minutes

def complement(intervals):
    """Given a sorted list of busy intervals within work hours, return free intervals."""
    free = []
    cur = WORK_START
    for s, e in sorted(intervals):
        if cur < s:
            free.append((cur, s))
        cur = max(cur, e)
    if cur < WORK_END:
        free.append((cur, WORK_END))
    return free

def intersect(a, b):
    """Intersect two lists of intervals."""
    i, j = 0, 0
    res = []
    while i < len(a) and j < len(b):
        s = max(a[i][0], b[j][0])
        e = min(a[i][1], b[j][1])
        if s < e:
            res.append((s, e))
        if a[i][1] < b[j][1]:
            i += 1
        else:
            j += 1
    return res

# Preferred day order: avoid Wednesday if possible
preferred_days = ['Thursday', 'Wednesday']

answer = None

for day in preferred_days:
    # Betty's day constraints
    if day in ('Monday', 'Tuesday'):
        continue
    if day == 'Thursday':
        earliest_start_allowed = to_min('15:00')
    else:
        earliest_start_allowed = WORK_START

    # Get free intervals for both participants
    betty_free = complement(busy['Betty'].get(day, []))
    scott_free = complement(busy['Scott'].get(day, []))
    common = intersect(betty_free, scott_free)

    # Search for a slot of required duration respecting earliest_start_allowed
    for s, e in common:
        start = max(s, earliest_start_allowed)
        while start + DURATION <= e:
            answer = (day, to_str(start), to_str(start + DURATION))
            break
        if answer:
