    if answer:
        break

# Fallback: if no slot found in preferred order (should not happen per problem statement)
if not answer:
    # Try all days in normal order as safety net
    all_days = ['Monday', 'Tuesday', 'Wednesday', 'Thursday']
    for day in all_days:
        if day in ('Monday', 'Tuesday'):
            continue
        earliest_start_allowed = to_min('15:00') if day == 'Thursday' else WORK_START
        betty_free = complement(busy['Betty'].get(day, []))
        scott_free = complement(busy['Scott'].get(day, []))
        common = intersect(betty_free, scott_free)
        for s, e in common:
            start = max(s, earliest_start_allowed)
            while start + DURATION <= e:
                answer = (day, to_str(start), to_str(start + DURATION))
                break
            if answer:
                break
        if answer:
