#!/usr/bin/env python3
import sys

# ---------- helper functions ----------
def hm_to_min(s: str) -> int:
    """'HH:MM' -> minutes since midnight."""
    h, m = map(int, s.split(":"))
    return h * 60 + m

def min_to_hm(m: int) -> str:
    """minutes since midnight -> 'HH:MM' zero‑padded."""
    return f"{m // 60:02d}:{m % 60:02d}"

def subtract_intervals(free, busy):
    """Subtract busy intervals from free intervals."""
    result = []
    for f_start, f_end in free:
        cur_start = f_start
        for b_start, b_end in busy:
            if b_end <= cur_start or b_start >= f_end:
                continue  # no overlap
            if b_start <= cur_start:
                cur_start = max(cur_start, b_end)
                continue
            # there is a gap before this busy interval
            result.append((cur_start, b_start))
            cur_start = max(cur_start, b_end)
        if cur_start < f_end:
            result.append((cur_start, f_end))
    return result

def intersect_intervals(a, b):
    """Return list of overlapped intervals between two interval lists."""
    i, j = 0, 0
    res = []
    while i < len(a) and j < len(b):
        a_start, a_end = a[i]
        b_start, b_end = b[j]
        start = max(a_start, b_start)
        end = min(a_end, b_end)
        if start < end:
            res.append((start, end))
        if a_end <= b_end:
            i += 1
        else:
            j += 1
    return res

# ---------- data ----------
DAYS = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday"]
WORK_START = hm_to_min("09:00")
WORK_END = hm_to_min("17:00")
MEETING_LEN = 30  # minutes

busy = {
    "Eugene": {
        "Monday":    [("11:00","12:00"), ("13:30","14:00"), ("14:30","15:00"), ("16:00","16:30")],
        "Wednesday":[("09:00","09:30"), ("11:00","11:30"), ("12:00","12:30"), ("13:30","15:00")],
        "Thursday": [("09:30","10:00"), ("11:00","12:30")],
        "Friday":   [("10:30","11:00"), ("12:00","12:30"), ("13:00","13:30")]
    },
    "Eric": {
        "Monday":   [("09:00","17:00")],
        "Tuesday":  [("09:00","17:00")],
        "Wednesday":[("09:00","11:30"), ("12:00","14:00"), ("14:30","16:30")],
        "Thursday": [("09:00","17:00")],
        "Friday":   [("09:00","11:00"), ("11:30","17:00")]
    }
}

# Convert string times to minutes
for person in busy:
    for day in busy[person]:
        busy[person][day] = [(hm_to_min(s), hm_to_min(e)) for s, e in busy[person][day]]

# ---------- compute free intervals ----------
free = {person: {} for person in busy}
for person in busy:
    for day in DAYS:
        # start from whole work day
        intervals = [(WORK_START, WORK_END)]
        # subtract busy intervals for that day (if any)
        intervals = subtract_intervals(intervals, busy[person].get(day, []))
        # store sorted
        free[person][day] = sorted(intervals)

# ---------- find common slots ----------
candidates = []  # (day_index, start, end)

for idx, day in enumerate(DAYS):
    # intersect free intervals of both participants
    common = intersect_intervals(free["Eugene"][day], free["Eric"][day])
    for start, end in common:
        if end - start >= MEETING_LEN:
            meeting_start = start  # earliest possible inside this interval
            meeting_end = meeting_start + MEETING_LEN
            candidates.append((idx, meeting_start, meeting_end))
            break  # only need earliest slot of the day

# ---------- choose best candidate ----------
if not candidates:
    sys.exit("No feasible meeting time found.")  # should not happen per statement

# Prefer non‑Wednesday (index 2) if possible
candidates.sort(key=lambda x: (x[0] == 2, x[0], x[1]))
chosen = candidates[0]
day_name = DAYS[chosen[0]]
start_str = min_to_hm(chosen[1])
end_str = min_to_hm(chosen[2])

# ---------- output ----------
print([day_name, start_str, end_str])

from datetime import datetime, timedelta

def to_minutes(t: str) -> int:
    h, m = map(int, t.split(":"))
    return h * 60 + m

def from_minutes(m: int) -> str:
    return f"{m // 60:02d}:{m % 60:02d}"

def merge_intervals(intervals):
    if not intervals:
        return []
    intervals.sort()
    merged = [intervals[0]]
    for start, end in intervals[1:]:
