from datetime import datetime, timedelta

# Helper functions
def to_minutes(t: str) -> int:
    """Convert HH:MM string to minutes since midnight."""
    h, m = map(int, t.split(":"))
    return h * 60 + m

def to_time_str(minutes: int) -> str:
    """Convert minutes since midnight to HH:MM zero‑padded."""
    h = minutes // 60
    m = minutes % 60
    return f"{h:02d}:{m:02d}"

def complement(busy, window_start, window_end):
    """Return free intervals inside [window_start, window_end) given busy list."""
    free = []
    cursor = window_start
    for s, e in sorted(busy):
        if s > cursor:
            free.append((cursor, s))
        cursor = max(cursor, e)
    if cursor < window_end:
        free.append((cursor, window_end))
    return free

def intersect(a, b):
    """Intersect two lists of intervals."""
    i, j = 0, 0
    res = []
    while i < len(a) and j < len(b):
        s1, e1 = a[i]
        s2, e2 = b[j]
        start = max(s1, s2)
        end = min(e1, e2)
        if start < end:
            res.append((start, end))
        if e1 < e2:
            i += 1
        else:
            j += 1
    return res

