import datetime

# Define work days and hours
DAYS = ["Monday", "Tuesday", "Wednesday"]
WORK_START = datetime.time(9, 0)
WORK_END = datetime.time(17, 0)
MEETING_DURATION = datetime.timedelta(hours=1)

# Participant busy schedules (day -> list of (start, end) times)
busy = {
    "Stephanie": {
        "Monday": [("09:30", "10:00"), ("10:30", "11:00"), ("11:30", "12:00"), ("14:00", "14:30")],
        "Tuesday": [("12:00", "13:00")],
        "Wednesday": [("09:00", "10:00"), ("13:00", "14:00")],
    },
    "Betty": {
        "Monday": [("09:00", "10:00"), ("11:00", "11:30"), ("14:30", "15:00"), ("15:30", "16:00")],
        "Tuesday": [("09:00", "09:30"), ("11:30", "12:00"), ("12:30", "14:30"), ("15:30", "16:00")],
        "Wednesday": [("10:00", "11:30"), ("12:00", "14:00"), ("14:30", "17:00")],
    },
}

def to_minutes(t: str) -> int:
    h, m = map(int, t.split(":"))
    return h * 60 + m

def minutes_to_time(m: int) -> str:
    return f"{m//60:02d}:{m%60:02d}"

def merge_intervals(intervals):
    """Merge overlapping intervals given as (start_min, end_min)."""
    if not intervals:
        return []
    intervals = sorted(intervals)
    merged = [intervals[0]]
    for cur_start, cur_end in intervals[1:]:
        last_start, last_end = merged[-1]
        if cur_start <= last_end:
            merged[-1] = (last_start, max(last_end, cur_end))
        else:
            merged.append((cur_start, cur_end))
    return merged

def day_free_slots(day):
    """Return list of (start_min, end_min) free slots within work hours for the given day."""
    work_start = to_minutes(WORK_START.strftime("%H:%M"))
    work_end = to_minutes(WORK_END.strftime("%H:%M"))
    busy_intervals = []
    for person in busy:
        for start, end in busy.get(person, {}).get(day, []):
            busy_intervals.append((to_minutes(start), to_minutes(end)))
    merged_busy = merge_intervals(busy_intervals)
    free = []
    cursor = work_start
    for b_start, b_end in merged_busy:
        if cursor < b_start:
            free.append((cursor, b_start))
        cursor = max(cursor, b_end)
    if cursor < work_end:
        free.append((cursor, work_end))
    return free

def satisfies_additional_constraints(day, start_min):
    """Check extra preferences/constraints."""
    # Stephanie prefers not to have more meetings on Monday
    # This is a soft preference handled later; here we only enforce hard constraints.
    # Betty cannot meet on Tuesday after 12:30
    if day == "Tuesday":
        limit = to_minutes("12:30")
        if start_min + MEETING_DURATION.total_seconds() // 60 > limit:
            return False
    return True

def find_meeting():
    best = None
    for day in DAYS:
        for free_start, free_end in day_free_slots(day):
            start = free_start
            while start + int(MEETING_DURATION.total_seconds() // 60) <= free_end:
                if satisfies_additional_constraints(day, start):
                    # Preference penalty: +1 if day is Monday (avoid if possible)
                    penalty = 1 if day == "Monday" else 0
                    candidate = (penalty, day, start)
                    if best is None or candidate < best:
                        best = candidate
                start += 1  # step minute by minute
    if best is None:
        raise ValueError("No feasible meeting time found")
    _, day, start_min = best
    end_min = start_min + int(MEETING_DURATION.total_seconds() // 60)
    return [day, minutes_to_time(start_min), minutes_to_time(end_min)]

print(find_meeting())
